}

async function readForm(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 1024 * 1024) {
      const error = new Error('Request too large');
      error.status = 413;
      throw error;
    }
  }
  return new URLSearchParams(body);
}

function sendHtml(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  response.end(body);
}

const server = http.createServer(async (request, response) => {
  try {
    const url = new URL(request.url, 'http://localhost');
    if (request.method === 'GET' && url.pathname === '/health') {
      response.writeHead(200, { 'Content-Type': 'application/json' });
      return response.end(JSON.stringify({ status: 'ok' }));
    }
    if (request.method === 'GET' && url.pathname === '/') {
      return sendHtml(response, 200, projectsPage('', '', projectFilter(url.searchParams.get('filter'))));
    }
    if (request.method === 'POST' && url.pathname === '/projects') {
      const form = await readForm(request);
      const enteredName = form.get('name') || '';
      const name = enteredName.trim();
      if (!name) return sendHtml(response, 200, projectsPage('Project name is required', enteredName, projectFilter(form.get('filter'))));
      createProject.run(name);
      response.writeHead(303, { Location: '/' });
      return response.end();
    }
    const renameMatch = url.pathname.match(/^\/projects\/([1-9]\d*)\/rename$/);
    if (request.method === 'POST' && renameMatch) {
      const project = getProject.get(renameMatch[1]);
      if (!project) return sendHtml(response, 404, page('Not found', '<h1>Not found</h1>'));
      if (project.archived) return sendHtml(response, 403, page('Archived project', '<h1>Archived project</h1><p>Restore the project to rename it.</p>'));
      const form = await readForm(request);
      const enteredName = form.get('name') || '';
      const name = enteredName.trim();
      const filter = taskFilter(form.get('filter'));
      if (!name) return sendHtml(response, 200, projectPage(project, filter, '', '', 'Project name is required', enteredName, null, priorityFilter(form.get('priorityFilter'))));
      renameProject.run(name, project.id);
      response.writeHead(303, { Location: projectLocation(project.id, filter, priorityFilter(form.get('priorityFilter'))) });
      return response.end();
    }
    const archiveMatch = url.pathname.match(/^\/projects\/([1-9]\d*)\/(archive|restore)$/);
    if (request.method === 'POST' && archiveMatch) {
      if (!getProject.get(archiveMatch[1])) return sendHtml(response, 404, page('Not found', '<h1>Not found</h1>'));
      setArchived.run(archiveMatch[2] === 'archive' ? 1 : 0, archiveMatch[1]);
      response.writeHead(303, { Location: archiveMatch[2] === 'archive' ? '/' : '/?filter=Archived' });
      return response.end();
    }
    const priorityMatch = url.pathname.match(/^\/projects\/([1-9]\d*)\/tasks\/([1-9]\d*)\/priority$/);
    if (request.method === 'POST' && priorityMatch) {
      const project = getProject.get(priorityMatch[1]);
      const task = project && getTask.get(priorityMatch[2], project.id);
      if (!task) return sendHtml(response, 404, page('Not found', '<h1>Not found</h1>'));
      if (project.archived) return sendHtml(response, 403, page('Archived project', '<h1>Archived project</h1><p>Restore the project to change its tasks.</p>'));
      const form = await readForm(request);
      const priority = form.get('priority');
      if (!['Low', 'Normal', 'High'].includes(priority)) {
        return sendHtml(response, 400, page('Invalid priority', '<h1>Invalid task priority</h1>'));
      }
      setTaskPriority.run(priority, task.id, project.id);
      response.writeHead(303, { Location: projectLocation(project.id, taskFilter(form.get('filter')), priorityFilter(form.get('priorityFilter'))) });
      return response.end();
    }
    const taskRenameMatch = url.pathname.match(/^\/projects\/([1-9]\d*)\/tasks\/([1-9]\d*)\/rename$/);
    if (request.method === 'POST' && taskRenameMatch) {
      const project = getProject.get(taskRenameMatch[1]);
      const task = project && getTask.get(taskRenameMatch[2], project.id);
      if (!task) return sendHtml(response, 404, page('Not found', '<h1>Not found</h1>'));
      if (project.archived) return sendHtml(response, 403, page('Archived project', '<h1>Archived project</h1><p>Restore the project to change its tasks.</p>'));
      const form = await readForm(request);
      const enteredTitle = form.get('title') || '';
      const title = enteredTitle.trim();
      const filter = taskFilter(form.get('filter'));
      if (!title) return sendHtml(response, 200, projectPage(project, filter, '', '', '', '', { id: task.id, title: enteredTitle }, priorityFilter(form.get('priorityFilter'))));
      renameTask.run(title, task.id, project.id);
      response.writeHead(303, { Location: projectLocation(project.id, filter, priorityFilter(form.get('priorityFilter'))) });
      return response.end();
    }
    const taskMatch = url.pathname.match(/^\/projects\/([1-9]\d*)\/tasks(?:\/([1-9]\d*))?$/);
    if (request.method === 'POST' && taskMatch) {
      const project = getProject.get(taskMatch[1]);
      if (!project || (taskMatch[2] && !getTask.get(taskMatch[2], project.id))) {
        return sendHtml(response, 404, page('Not found', '<h1>Not found</h1>'));
      }
      if (project.archived) return sendHtml(response, 403, page('Archived project', '<h1>Archived project</h1><p>Restore the project to change its tasks.</p>'));
      const form = await readForm(request);
      const filter = taskFilter(form.get('filter'));
      if (taskMatch[2]) {
        completeTask.run(form.get('completed') === '1' ? 1 : 0, taskMatch[2], project.id);
      } else {
        const enteredTitle = form.get('title') || '';
        const title = enteredTitle.trim();
        if (!title) return sendHtml(response, 200, projectPage(project, filter, 'Task title is required', enteredTitle, '', '', null, priorityFilter(form.get('priorityFilter'))));
        createTask.run(project.id, title);
      }
      response.writeHead(303, { Location: projectLocation(project.id, filter, priorityFilter(form.get('priorityFilter'))) });
      return response.end();
    }
    const match = url.pathname.match(/^\/projects\/([1-9]\d*)$/);
    if (request.method === 'GET' && match) {
      const project = getProject.get(match[1]);
      if (project) return sendHtml(response, 200, projectPage(project, taskFilter(url.searchParams.get('filter')), '', '', '', '', null, priorityFilter(url.searchParams.get('priorityFilter'))));
    }
    sendHtml(response, 404, page('Not found', '<h1>Not found</h1><a href="/">Projects</a>'));
  } catch (error) {
    console.error(error);
    if (!response.headersSent) sendHtml(response, error.status || 500, page('Error', `<h1>${error.status === 413 ? 'Request too large' : 'Something went wrong'}</h1>`));
    else response.end();
  }
});
server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
}

{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdir, mkdtemp, rm } from 'node:fs/promises';
import path from 'node:path';
import { DatabaseSync } from 'node:sqlite';

async function launch(databasePath) {
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: '0', DB_PATH: databasePath },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let errors = '';
  child.stderr.on('data', (data) => { errors += data; });
  const port = await new Promise((resolve, reject) => {
    let output = '';
    child.stdout.on('data', (data) => {
      output += data;
      const match = output.match(/listening on port (\d+)/);
      if (match) resolve(match[1]);
    });
    child.once('error', reject);
    child.once('exit', (code) => reject(new Error(`Server exited ${code}: ${errors}`)));
  });
  return {
    url: `http://127.0.0.1:${port}`,
    async stop() {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    },
  };
}

test('combined filters retain selections, re-evaluate edits, and work in archives', async () => {
  await mkdir('data', { recursive: true });
  const directory = await mkdtemp('data/combined-filter-test-');
  const databasePath = path.resolve(directory, 'projects.sqlite');
  let server;
  try {
    server = await launch(databasePath);
    const post = (route, values = {}) => fetch(server.url + route, {
      method: 'POST', body: new URLSearchParams(values), redirect: 'manual',
    });
    const html = async (route) => (await fetch(server.url + route)).text();
    const titles = (markup) => [...markup.matchAll(/aria-label="Complete ([^"]*)"/g)].map((match) => match[1]);
    const selected = (markup, id, value) => assert.match(markup,
      new RegExp(`<select id="${id}"[^>]*>[\\s\\S]*?<option selected>${value}</option>`));
    await post('/projects', { name: 'One' });
    for (const title of ['First', 'Second', 'Third', 'Fourth']) await post('/projects/1/tasks', { title });
    await post('/projects/1/tasks/1/priority', { priority: 'High' });
    await post('/projects/1/tasks/3/priority', { priority: 'High' });
    await post('/projects/1/tasks/4/priority', { priority: 'Low' });
    await post('/projects/1/tasks/3', { completed: '1' });
    await post('/projects/1/tasks/4', { completed: '1' });
    const expected = {
      All: { All: ['First', 'Second', 'Third', 'Fourth'], Low: ['Fourth'], Normal: ['Second'], High: ['First', 'Third'] },
      Open: { All: ['First', 'Second'], Low: [], Normal: ['Second'], High: ['First'] },
      Completed: { All: ['Third', 'Fourth'], Low: ['Fourth'], Normal: [], High: ['Third'] },
    };
    const summary = await html('/');
    for (const [filter, priorities] of Object.entries(expected)) {
      for (const [priorityFilter, rows] of Object.entries(priorities)) {
        const markup = await html(`/projects/1?filter=${filter}&priorityFilter=${priorityFilter}`);
        assert.deepEqual(titles(markup), rows);
        selected(markup, 'task-filter', filter);
        selected(markup, 'priority-filter', priorityFilter);
      }
    }
    const initial = await html('/projects/1');
    assert.match(initial, /id="priority-filter"[^>]*>\s*<option selected>All<\/option><option>Low<\/option><option>Normal<\/option><option>High<\/option>/);
    const selections = { filter: 'Open', priorityFilter: 'High' };
    const route = '/projects/1?filter=Open&priorityFilter=High';
    const invalid = await (await post('/projects/1/tasks/1/rename', { ...selections, title: '  ' })).text();
    assert.match(invalid, /role="alert">Task title is required/);
    selected(invalid, 'task-filter', 'Open');
    selected(invalid, 'priority-filter', 'High');
    const renamed = await post('/projects/1/tasks/1/rename', { ...selections, title: ' Renamed ' });
    assert.equal(renamed.headers.get('location'), route);
    assert.deepEqual(titles(await html(route)), ['Renamed']);
    assert.equal(await html('/'), summary);
    const reprioritized = await post('/projects/1/tasks/1/priority', { ...selections, priority: 'Normal' });
    assert.equal(reprioritized.headers.get('location'), route);
    assert.deepEqual(titles(await html(route)), []);
    assert.equal(await html('/'), summary);
    await post('/projects/1/tasks/2/priority', { priority: 'High' });
    const completed = await post('/projects/1/tasks/2', { ...selections, completed: '1' });
    assert.equal(completed.headers.get('location'), route);
    assert.deepEqual(titles(await html(route)), []);
    assert.deepEqual(titles(await html('/projects/1?filter=Completed&priorityFilter=High')), ['Second', 'Third']);
    await server.stop();
    server = await launch(databasePath);
    assert.deepEqual(titles(await html('/projects/1?filter=Completed&priorityFilter=High')), ['Second', 'Third']);
    await post('/projects/1/archive');
    const archived = await html('/projects/1?filter=Completed&priorityFilter=High');
    assert.deepEqual(titles(archived), ['Second', 'Third']);
    assert.match(archived, /id="task-priority-2"[^>]* disabled/);
    assert.doesNotMatch(archived, /id="(?:task-filter|priority-filter)"[^>]* disabled/);
    await post('/projects/1/restore');
    assert.deepEqual(titles(await html('/projects/1?filter=Completed&priorityFilter=High')), ['Second', 'Third']);
    selected(await html('/projects/1'), 'priority-filter', 'All');
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

test('priorities migrate, persist independently, and respect ownership and archives', async () => {
  await mkdir('data', { recursive: true });
  const directory = await mkdtemp('data/priority-test-');
  const databasePath = path.resolve(directory, 'projects.sqlite');
  const oldDb = new DatabaseSync(databasePath);
  oldDb.exec(`CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL);
    INSERT INTO projects (name) VALUES ('One'), ('Two');
    CREATE TABLE tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL, title TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0);
    INSERT INTO tasks (project_id, title, completed) VALUES (1, 'Existing', 1);`);
  oldDb.close();
  let server;
  try {
    server = await launch(databasePath);
    const post = (route, values = {}) => fetch(server.url + route, {
      method: 'POST', body: new URLSearchParams(values), redirect: 'manual',
    });
    const html = async (route) => (await fetch(server.url + route)).text();
    const priorityOptions = (markup, id) => markup.match(new RegExp(`<select id="task-priority-${id}"[^>]*>([\\s\\S]*?)</select>`))[1].trim();
    const normal = '<option>Low</option><option selected>Normal</option><option>High</option>';
    assert.equal(priorityOptions(await html('/projects/1'), 1), normal);
    await post('/projects/1/tasks', { title: 'New' });
    await post('/projects/2/tasks', { title: 'Other' });
    assert.equal(priorityOptions(await html('/projects/1'), 2), normal);
    const summary = await html('/');
    const changed = await post('/projects/1/tasks/1/priority', { priority: 'High', filter: 'Completed' });
    assert.equal(changed.status, 303);
    assert.equal(changed.headers.get('location'), '/projects/1?filter=Completed');
    await post('/projects/1/tasks/2/priority', { priority: 'Low' });
    assert.equal((await post('/projects/2/tasks/1/priority', { priority: 'Low' })).status, 404);
    assert.equal((await post('/projects/1/tasks/999/priority', { priority: 'Low' })).status, 404);
    assert.equal((await post('/projects/1/tasks/1/priority', { priority: 'Urgent' })).status, 400);
    await post('/projects/1/tasks/1/rename', { title: 'Renamed' });
